-- Jalankan di Supabase > SQL Editor.
create table if not exists public.products (
 id bigint generated by default as identity primary key,
 name text not null, category text not null check(category in ('Minuman','Makanan')),
 price integer not null default 25000 check(price>=0), image_url text, description text,
 is_available boolean not null default true, created_at timestamptz not null default now()
);
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
alter table public.products enable row level security;
alter table public.admins enable row level security;
drop policy if exists "Public can read available products" on public.products;
create policy "Public can read available products" on public.products for select to anon,authenticated using(is_available=true);
drop policy if exists "Admins can read all products" on public.products;
create policy "Admins can read all products" on public.products for select to authenticated using(exists(select 1 from public.admins a where a.user_id=auth.uid()));
drop policy if exists "Admins can insert products" on public.products;
create policy "Admins can insert products" on public.products for insert to authenticated with check(exists(select 1 from public.admins a where a.user_id=auth.uid()));
drop policy if exists "Admins can update products" on public.products;
create policy "Admins can update products" on public.products for update to authenticated using(exists(select 1 from public.admins a where a.user_id=auth.uid())) with check(exists(select 1 from public.admins a where a.user_id=auth.uid()));
drop policy if exists "Admins can delete products" on public.products;
create policy "Admins can delete products" on public.products for delete to authenticated using(exists(select 1 from public.admins a where a.user_id=auth.uid()));
drop policy if exists "Admins can read own admin row" on public.admins;
create policy "Admins can read own admin row" on public.admins for select to authenticated using(user_id=auth.uid());
insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict(id) do update set public=true;
drop policy if exists "Public can view product images" on storage.objects;
create policy "Public can view product images" on storage.objects for select to anon,authenticated using(bucket_id='product-images');
drop policy if exists "Admins can upload product images" on storage.objects;
create policy "Admins can upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and exists(select 1 from public.admins a where a.user_id=auth.uid()));
drop policy if exists "Admins can update product images" on storage.objects;
create policy "Admins can update product images" on storage.objects for update to authenticated using(bucket_id='product-images' and exists(select 1 from public.admins a where a.user_id=auth.uid())) with check(bucket_id='product-images' and exists(select 1 from public.admins a where a.user_id=auth.uid()));
drop policy if exists "Admins can delete product images" on storage.objects;
create policy "Admins can delete product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and exists(select 1 from public.admins a where a.user_id=auth.uid()));
insert into public.products(name,category,price)
select v.name,v.category,25000 from (values ('Ice Lemonade','Minuman'),('Kiwi Tea','Minuman'),('Strawberry Tea','Minuman'),('Grape Tea','Minuman'),('Chicken Wings','Makanan'),('Chicken Mid Wings','Makanan')) v(name,category)
where not exists(select 1 from public.products p where p.name=v.name);
